  {
    method: 'POST',
    headers: {
      'X-Api-Key': API_KEY,
      'Content-Type': 'application/json'  // ⚠️ REQUIRED
    },
    body: JSON.stringify({
      answer,                           // Required — see formats above
      ttcMs: Date.now() - startTime,    // Optional — used for speed s
